glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);
  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 smokeColor;
  vec4 smokeAnchor;
  vec4 smokeShape;
  vec4 smokePack0;
  vec4 smokePack1;
  vec4 smokePack2;
  vec4 smokePack3;
  vec4 smokePack4;
  vec4 smokePack5;
  vec4 smokePack6;
  float colorAdjustEnabled;
  float hueShift;
  float saturationMul;
  float valueMul;
  float colorAdjustStrength;
  float colorAdjustWhiteProtect;
};

vec3 rgbToYiq(vec3 rgb) {
  return vec3(
    dot(rgb, vec3(0.299, 0.587, 0.114)),
    dot(rgb, vec3(0.596, -0.274, -0.322)),
    dot(rgb, vec3(0.211, -0.523, 0.312))
  );
}

vec3 yiqToRgb(vec3 yiq) {
  return clamp(vec3(
    yiq.x + 0.956 * yiq.y + 0.621 * yiq.z,
    yiq.x - 0.272 * yiq.y - 0.647 * yiq.z,
    yiq.x - 1.106 * yiq.y + 1.703 * yiq.z
  ), 0.0, 1.0);
}

vec3 applyPsHueYiq(vec3 rgb, float hueShiftVal) {
  vec3 yiq = rgbToYiq(max(rgb, vec3(0.0)));
  float chroma = length(yiq.yz);
  float hue = chroma > 1.0e-5 ? atan(yiq.z, yiq.y) : 0.0;
  hue += hueShiftVal * 6.28318530718;
  yiq.yz = vec2(cos(hue), sin(hue)) * chroma;
  return yiqToRgb(yiq);
}

vec3 applyPsSaturationRec709(vec3 rgb, float sat) {
  float s = max(0.0, sat);
  vec3 safe = max(rgb, vec3(0.0));
  float luma = dot(safe, vec3(0.2125, 0.7154, 0.0721));
  return mix(vec3(luma), safe, s);
}

float bakedRec709Luminance(vec3 rgb) {
  return dot(max(rgb, vec3(0.0)), vec3(0.2126, 0.7152, 0.0722));
}

vec3 applyCompanionValueScale(vec3 sourceRgb, float valueMul, float strength) {
  float s = clamp(strength, 0.0, 1.0);
  float vm = clamp(valueMul, 0.0, 1.0);
  vec3 safe = max(sourceRgb, vec3(0.0));
  if (s <= 0.00001) {
    return safe;
  }
  float luma = bakedRec709Luminance(safe);
  float yScaled = vm;
  vec3 adjusted = clamp(vec3(yScaled) + (safe - luma), 0.0, 1.0);
  return mix(safe, adjusted, s);
}

vec3 applySmokeBakedColorAdjust(vec3 rgb) {
  if (colorAdjustEnabled <= 0.5) {
    return rgb;
  }
  float strength = clamp(colorAdjustStrength, 0.0, 1.0);
  vec3 outRgb = rgb;
  vec3 hueOnlyRgb = applyPsHueYiq(outRgb, hueShift);
  outRgb = mix(outRgb, hueOnlyRgb, strength);
  outRgb = applyCompanionValueScale(outRgb, valueMul, strength);
  vec3 satBoosted = applyPsSaturationRec709(outRgb, saturationMul);
  outRgb = mix(outRgb, satBoosted, strength);
  return outRgb;
}

vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 mod289(vec4 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 permute(vec4 x) {
  return mod289(((x * 34.0) + 1.0) * x);
}

vec4 taylorInvSqrt(vec4 r) {
  return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec3 v) {
  const vec2 C = vec2(1.0 / 6.0, 1.0 / 3.0);
  const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);

  vec3 i = floor(v + dot(v, C.yyy));
  vec3 x0 = v - i + dot(i, C.xxx);

  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min(g.xyz, l.zxy);
  vec3 i2 = max(g.xyz, l.zxy);

  vec3 x1 = x0 - i1 + C.xxx;
  vec3 x2 = x0 - i2 + C.yyy;
  vec3 x3 = x0 - D.yyy;

  i = mod289(i);
  vec4 p = permute(permute(permute(
    i.z + vec4(0.0, i1.z, i2.z, 1.0))
    + i.y + vec4(0.0, i1.y, i2.y, 1.0))
    + i.x + vec4(0.0, i1.x, i2.x, 1.0));

  float n_ = 0.142857142857;
  vec3 ns = n_ * D.wyz - D.xzx;

  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);

  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_);

  vec4 x = x_ * ns.x + ns.yyyy;
  vec4 y = y_ * ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);

  vec4 b0 = vec4(x.xy, y.xy);
  vec4 b1 = vec4(x.zw, y.zw);

  vec4 s0 = floor(b0) * 2.0 + 1.0;
  vec4 s1 = floor(b1) * 2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));

  vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
  vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;

  vec3 p0 = vec3(a0.xy, h.x);
  vec3 p1 = vec3(a0.zw, h.y);
  vec3 p2 = vec3(a1.xy, h.z);
  vec3 p3 = vec3(a1.zw, h.w);

  vec4 norm = taylorInvSqrt(vec4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
  p0 *= norm.x;
  p1 *= norm.y;
  p2 *= norm.z;
  p3 *= norm.w;

  vec4 m = max(0.6 - vec4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
  m = m * m;
  return 42.0 * dot(m * m, vec4(dot(p0, x0), dot(p1, x1), dot(p2, x2), dot(p3, x3)));
}

float smin(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  return fract((p + p) * p);
}

float lifeEnvelope(float t, float power) {
  return pow(clamp(t, 0.0, 1.0), max(power, 0.05));
}

float evaluateSDF(vec2 uv, float t_time, float phaseScale, float lifecycleFrac, float decayPower) {
  float distortSpeed = smokePack0.x;
  float asymmetryStrength = smokePack0.y;
  float blobGrowth = smokePack0.w;
  float sminK = smokePack1.x;
  float blobScale = smokePack5.x;
  float ballCount = smokePack5.y;
  float meanderPower = smokePack5.z;
  if (meanderPower < 1.0) {
    meanderPower = 2.0;
  }
  meanderPower = clamp(meanderPower, 1.0, 4.0);

  float bulgePower = mix(2.5, 4.0, clamp(blobGrowth / 0.35, 0.0, 1.0));
  float surfaceNoiseAmp = clamp(smokePack6.z, 0.0, 0.15);
  float stackDensityY = smokePack4.z;
  float stackDensityX = smokePack4.w;
  float motionSeed = smokePack2.y;
  float motionVariance = smokePack2.z;
  float lifeFrac = max(lifecycleFrac, 0.15);

  float sdf = 1e5;
  float speed = max(0.05, distortSpeed);
  float asym = asymmetryStrength;
  float growth = clamp(blobGrowth, 0.0, 0.35);
  float mergeK = clamp(sminK, 0.0, 0.25);
  float scale = clamp(blobScale, 0.7, 1.4);
  float count = clamp(floor(ballCount + 0.5), 4.0, float(24));
  float evenSpacing = 1.0 / count;
  float vDensity = clamp(stackDensityY, 0.0, 5.0);
  float hDensity = clamp(stackDensityX, 0.5, 5.0);
  float spacing = vDensity <= 0.001
    ? evenSpacing
    : clamp(evenSpacing / vDensity, 0.0, evenSpacing);
  float seed = motionSeed;
  float variance = clamp(motionVariance, 0.0, 1.5);

  for (int i = 0; i < 24; i++) {
    float fi = float(i);
    if (fi >= count) {
      break;
    }
    float ballSpeed = speed;
    float phaseOff = hash11(seed + fi * 7.31) * max(spacing, evenSpacing * 0.25) * variance;
    float phaseBase = t_time * ballSpeed + fi * spacing + phaseOff;
    float lifeT = fract(phaseBase);
    float lifeTInv = 1.0 - lifeT;
    float meanderEnv = lifeEnvelope(lifeT, meanderPower);
    float swing = sin(lifeT * 6.28 + fi * 1.7 + seed * 0.37 * variance) * asym * 0.12 * meanderEnv;
    float x = 0.5 + swing / hDensity;
    vec2 center = vec2(x, lifeT);
    float bulgeEnv = lifeEnvelope(lifeTInv, bulgePower);
    float decayEnv = lifeEnvelope(lifeTInv, decayPower);
    float baseR = (0.04 + growth * bulgeEnv) * phaseScale * scale / lifeFrac;
    float pulse = 1.0 + 0.08 * variance * sin(t_time * (3.2 + hash11(seed + fi * 5.3)) + fi * 1.3 + seed) * decayEnv;
    float r = baseR * pulse;
    vec2 dir = uv - center;
    float angle = atan(dir.y, dir.x);
    float polarNoise = snoise(vec3(cos(angle * 1.2), sin(angle * 1.2), t_time * 0.8 + fi + seed * 0.01));
    r += polarNoise * surfaceNoiseAmp * decayEnv / lifeFrac;
    float d = length(dir) - r;
    if (i == 0) {
      sdf = d;
    } else if (mergeK <= 0.001) {
      sdf = min(sdf, d);
    } else {
      sdf = smin(sdf, d, max(mergeK, 0.05));
    }
  }

  return sdf;
}

void main () {
  float edgeSoftness = smokePack1.y;
  float fadeHeight = clamp(smokePack1.z, 0.0, 0.95);
  float entrancePhase = smokePack1.w;
  float flipY = smokePack3.z;
  float spreadScale = smokePack3.w;
  float aspectRatio = smokePack4.x;
  float domainWarpAmp = clamp(smokePack4.y, 0.0, 0.15);
  float decayPower = smokePack6.x > 0.001 ? clamp(smokePack6.x, 0.05, 4.0) : 0.5;
  float deathEnvelope = smokePack6.y > 0.001 ? clamp(smokePack6.y, 0.05, 4.0) : 1.0;
  float edgeErosion = clamp(smokePack6.w, 0.0, 0.35);
  float time = smokePack2.x;

  float emitTopY = smokeAnchor.x;
  float emitBottomY = smokeAnchor.y;
  float headroomTop = max(0.02, smokeAnchor.z);
  float headroomBottom = max(0.02, smokeAnchor.w);

  float fadeRefHeadroom = 0.35;
  float lifecycleFracTop = clamp(smokeShape.x, 0.15, 5.0);
  float lifecycleFracBottom = smokeShape.y > 0.001
    ? clamp(smokeShape.y, 0.15, 5.0)
    : lifecycleFracTop;
  float emitInset = clamp(smokePack3.x, 0.0, 0.15);
  float cardSpan = max(emitTopY - emitBottomY, 0.02);
  emitInset = min(emitInset, cardSpan * 0.45);
  float spawnTopY = emitTopY - emitInset;
  float spawnBottomY = emitBottomY + emitInset;
  float flipSign = step(0.5, clamp(flipY, 0.0, 1.0));
  float spread = max(0.3, spreadScale);
  float isoAspect = max(aspectRatio, 0.01);
  float widthX = clamp(smokeShape.z, 0.15, 1.5);
  float opacityMul = clamp(smokeShape.w, 0.0, 3.0);
  float phaseScale = smoothstep(0.0, 1.0, clamp(entrancePhase, 0.0, 1.0));
  float outerSoftW = max(0.005, edgeSoftness * 0.12);

  if (phaseScale <= 0.001) {
    gl_FragColor = vec4(0.0);
    return;
  }

  vec2 contentUV = v_uv0;
  if (contentUV.x < 0.0 || contentUV.x > 1.0 || contentUV.y < 0.0 || contentUV.y > 1.0) {
    gl_FragColor = vec4(0.0);
    return;
  }

  float lifeAlphaStartTop = clamp(smokePack3.y, 0.0, 0.95);
  float lifeAlphaStartBottom = smokePack2.w > 0.001
    ? clamp(smokePack2.w, 0.0, 0.95)
    : lifeAlphaStartTop;
  float lifeAlphaPower = smokePack0.z > 0.001 ? clamp(smokePack0.z, 0.05, 4.0) : 2.0;

  float normY = mix(contentUV.y, 1.0 - contentUV.y, flipSign);
  vec2 localUV = vec2(0.5, 0.0);
  float spawnFade = 1.0;
  float timeOffset = 0.0;
  float activeLifecycleFrac = lifecycleFracTop;
  bool isBottomZone = false;
  float emitLine = max(emitBottomY, 0.0);
  float spawnLine = emitLine - emitInset;

  if (emitTopY > 0.0 && emitBottomY < emitTopY) {
    if (normY > spawnTopY + 0.001) {
      localUV.y = clamp((normY - spawnTopY) / max(0.02, headroomTop), 0.0, 1.0);
      localUV.x = contentUV.x;
      activeLifecycleFrac = lifecycleFracTop;
      isBottomZone = false;
      if (emitInset > 0.001) {
        float edgeT = emitInset / max(0.02, fadeRefHeadroom);
        spawnFade = smoothstep(0.0, edgeT, localUV.y);
      }
    } else if (normY < spawnBottomY - 0.001) {
      localUV.y = clamp((spawnBottomY - normY) / max(0.02, headroomBottom), 0.0, 1.0);
      localUV.x = contentUV.x;
      activeLifecycleFrac = lifecycleFracBottom;
      isBottomZone = true;
      timeOffset = 137.54;
      if (emitInset > 0.001) {
        float edgeT = emitInset / max(0.02, fadeRefHeadroom);
        spawnFade = smoothstep(0.0, edgeT, localUV.y);
      }
    } else {
      gl_FragColor = vec4(0.0);
      return;
    }
  } else if (normY > spawnLine + 0.001) {
    localUV.y = clamp((normY - spawnLine) / max(0.02, headroomBottom), 0.0, 1.0);
    localUV.x = contentUV.x;
    activeLifecycleFrac = lifecycleFracTop;
    if (emitInset > 0.001) {
      float edgeT = emitInset / max(0.02, fadeRefHeadroom);
      spawnFade = smoothstep(0.0, edgeT, localUV.y);
    }
  } else {
    gl_FragColor = vec4(0.0);
    return;
  }

  float lifeFrac = max(activeLifecycleFrac, 0.15);
  float lifeTFrag = localUV.y;
  float activeHeadroom = isBottomZone ? headroomBottom : headroomTop;
  float fadeLifeT = clamp(lifeTFrag * activeHeadroom / max(0.02, fadeRefHeadroom), 0.0, 1.0);
  vec2 targetUV;
  targetUV.y = lifeTFrag / lifeFrac;
  targetUV.x = (localUV.x - 0.5) / lifeFrac * isoAspect + 0.5;
  targetUV.x = 0.5 + (targetUV.x - 0.5) / widthX;

  vec2 sdfUV = vec2(0.5, 0.0) + (targetUV - vec2(0.5, 0.0)) / spread;

  float t_time = ((time > 0.0) ? time : cc_time.x) + timeOffset;
  float columnLifeInv = 1.0 - lifeTFrag;
  float columnDecayEnv = lifeEnvelope(columnLifeInv, decayPower);
  vec2 warp;
  warp.x = snoise(vec3(sdfUV * 3.0, t_time * 0.4));
  warp.y = snoise(vec3(sdfUV * 3.0 + vec2(17.3, 31.1), t_time * 0.4));
  vec2 warpedUV = sdfUV + warp * domainWarpAmp * columnDecayEnv;
  float sdfVal = evaluateSDF(warpedUV, t_time, phaseScale, lifeFrac, decayPower);
  float erosionNoise = snoise(vec3(sdfUV * 12.0, t_time * 1.5)) * edgeErosion * columnDecayEnv;
  float softW = outerSoftW + abs(erosionNoise) * 0.35;
  float sdfBias = erosionNoise * 0.02;

  float fillMask = sdfVal < 0.0
    ? 1.0
    : 1.0 - smoothstep(0.0, softW, sdfVal - sdfBias);

  if (fillMask <= 0.001) {
    gl_FragColor = vec4(0.0);
    return;
  }

  vec3 finalColor = applySmokeBakedColorAdjust(smokeColor.rgb);
  float columnFadeLifeInv = 1.0 - fadeLifeT;
  float topFade = lifeEnvelope(columnFadeLifeInv, deathEnvelope);
  if (fadeHeight > 0.001) {
    float fadeEnd = min(fadeHeight + 0.28, 1.0);
    topFade *= 1.0 - smoothstep(fadeHeight, fadeEnd, fadeLifeT);
  }
  float activeLifeAlphaStart = isBottomZone ? lifeAlphaStartBottom : lifeAlphaStartTop;
  if (activeLifeAlphaStart > 0.001 && activeLifeAlphaStart < 0.999) {
    float lifeTNorm = clamp(fadeLifeT / lifeFrac, 0.0, 1.0);
    float lifeFadeT = (lifeTNorm - activeLifeAlphaStart) / max(0.01, 1.0 - activeLifeAlphaStart);
    topFade *= 1.0 - lifeEnvelope(lifeFadeT, lifeAlphaPower);
  }
  float alpha = fillMask * spawnFade * topFade * opacityMul * smokeColor.a;
  alpha = clamp(alpha, 0.0, 1.0);

  if (alpha <= 0.001) {
    gl_FragColor = vec4(0.0);
    return;
  }

  #if USE_TEXTURE
    vec4 baseTex = texture2D(texture, v_uv0);
    #if CC_USE_ALPHA_ATLAS_TEXTURE
      alpha *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
    #endif
  #else
    vec4 baseTex = vec4(1.0);
  #endif

  gl_FragColor = vec4(finalColor, alpha * baseTex.a) * v_color;
}

